def algorithm(func, dim, lb, ub, budget, rng):
    n = len(lb)
    x = np.random.uniform(lb, ub, (1, n))
    best_x = x.copy()
    best_f = func(x)

    for i in range(budget):
        perturb_radius = 0.5
        while True:
            x_new = x + perturb_radius * rng.normal(size=(1, n)) 
            x_new = np.clip(x_new, lb, ub)

            if (np.abs(rng.uniform(-1, 1, size=n) < perturb_radius)).all():
                f_new = func(x_new)
            else:
                x_new += rng.uniform(lb - x + 1e-6, ub - x + 1e-6, size=(1, n))
                f_new = func(x_new)

            if f_new < best_f or i == budget - 1:
                break

            perturb_radius *= np.exp(rng.uniform(-0.9, -0.1))

        if f_new < best_f and rng.uniform(0, 1) > 0.2:
            best_x = x_new.copy()
            best_f = f_new

        x = x_new.copy()

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    x = np.random.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        y = x + 0.5 * (rng.rand(dim) - 0.5) * (ub - lb)
        z = clip(y)

        f1 = func(z)
        if f1 < best_f:
            best_x = z.copy()
            best_f = f1

        f2 = func(x + rng.uniform(-1, 1))
        if np.random.rand() < np.exp((best_f - f1) / (f1 + 1e-8)):
            x = clip(z)
        else:
            x = x + rng.uniform(-1, 1)

    return best_x

